package bannercase

import "testing"

func TestBannerText(t *testing.T) {
	want := "Welcome!"
	if NewUIEnabled {
		want = "Welcome to the NEW UI!"
	}
	if got := BannerText(); got != want {
		t.Fatalf("BannerText() = %q, want %q (the CURRENT flag, not a stale value)", got, want)
	}
}

